import * as react from 'react';

/**
 * Paletas de color y escalas para los mapas de @webrek/mx-geo. Este módulo no
 * depende de React: son funciones puras que también puedes usar para construir
 * tu propia leyenda o pintar el TopoJSON con otra herramienta.
 */
/** Una paleta es una lista de 2 o más colores hex (`#rrggbb`) de claro a oscuro. */
type Paleta = readonly string[];
/**
 * Paletas secuenciales (un solo tono, de claro a oscuro) listas para usar como
 * choropleth. La clave es el nombre que aceptan los componentes en la prop
 * `paleta`.
 */
declare const PALETAS: {
    readonly azul: readonly ["#eff6ff", "#93c5fd", "#3b82f6", "#1e3a8a"];
    readonly verde: readonly ["#f0fdf4", "#86efac", "#22c55e", "#166534"];
    readonly rojo: readonly ["#fef2f2", "#fca5a5", "#ef4444", "#991b1b"];
    readonly naranja: readonly ["#fff7ed", "#fdba74", "#f97316", "#9a3412"];
    readonly morado: readonly ["#faf5ff", "#d8b4fe", "#a855f7", "#6b21a8"];
    readonly teal: readonly ["#f0fdfa", "#5eead4", "#14b8a6", "#115e59"];
    readonly rosa: readonly ["#fdf2f8", "#f9a8d4", "#ec4899", "#9d174d"];
    readonly ambar: readonly ["#fffbeb", "#fcd34d", "#f59e0b", "#92400e"];
    readonly gris: readonly ["#f9fafb", "#d1d5db", "#6b7280", "#1f2937"];
    /** Marca Walmart (azul corporativo). */
    readonly walmart: readonly ["#e6f2fb", "#79bdec", "#0071ce", "#003b73"];
};
/** Paletas divergentes (dos tonos con punto medio claro), para datos con centro. */
declare const PALETAS_DIVERGENTES: {
    readonly rojoVerde: readonly ["#991b1b", "#fca5a5", "#f3f4f6", "#86efac", "#166534"];
    readonly azulRojo: readonly ["#1e3a8a", "#93c5fd", "#f3f4f6", "#fca5a5", "#991b1b"];
    readonly moradoVerde: readonly ["#6b21a8", "#d8b4fe", "#f3f4f6", "#86efac", "#166534"];
};
/** Nombre de una paleta secuencial integrada. */
type NombrePaleta = keyof typeof PALETAS;
/** Nombre de una paleta divergente integrada. */
type NombrePaletaDivergente = keyof typeof PALETAS_DIVERGENTES;
/** Lo que aceptan los componentes en `paleta`: un nombre integrado o tus colores. */
type PaletaInput = NombrePaleta | NombrePaletaDivergente | Paleta;

/** Coordenada geográfica `[longitud, latitud]` en grados. */
type LonLat = [number, number];

/** Un municipio (o alcaldía) con sus claves de INEGI. */
interface Municipio {
    /** CVEGEO de 5 dígitos: clave de entidad (2) + clave de municipio (3). */
    cvegeo: string;
    /** CVE_ENT del estado al que pertenece (2 dígitos). */
    cve_ent: string;
    /** CVE_MUN dentro del estado (3 dígitos). */
    cve_mun: string;
    /** Nombre del municipio. */
    nombre: string;
}
/** TopoJSON de los municipios de un estado (un objeto). */
interface MunicipiosEstadoTopo {
    type: "Topology";
    objects: Record<string, {
        type: "GeometryCollection";
        geometries: Array<{
            properties: Municipio;
        }>;
    }>;
    arcs: number[][][];
    transform?: {
        scale: [number, number];
        translate: [number, number];
    };
}
/** Lista de municipios (índice ligero, sin geometría); filtra por CVE_ENT. */
declare function municipios(cveEnt?: string): Municipio[];
/** Devuelve un municipio por su CVEGEO, o `null`. */
declare function municipio(cvegeo: string): Municipio | null;
/** Carga (con caché) el TopoJSON de los municipios de un estado por su CVE_ENT. */
declare function cargaMunicipios(cveEnt: string): Promise<MunicipiosEstadoTopo>;
/**
 * Geocodificación inversa a nivel municipio: de una coordenada `[lon, lat]` al
 * CVEGEO del municipio que la contiene, o `null` si cae fuera de México.
 *
 * Primero ubica el estado con {@link estadoDeCoordenada} y solo entonces carga
 * la geometría municipal de ESE estado (un chunk), así que es barato. Es
 * asíncrona porque la geometría municipal se carga bajo demanda.
 *
 * ```ts
 * await municipioDeCoordenada([-99.1332, 19.4326]); // "09015" (Cuauhtémoc)
 * ```
 */
declare function municipioDeCoordenada(punto: LonLat): Promise<string | null>;
type Props = {
    /** Clave del estado (CVE_ENT) cuyos municipios se dibujan, p. ej. "09". */
    estado: string;
    /** Valores por CVEGEO, p. ej. `{ "09012": 1200 }`. */
    data?: Record<string, number>;
    onSelect?: (municipio: Municipio) => void;
    /**
     * Paleta del choropleth: nombre integrado (`"verde"`, `"azul"`…) o lista de
     * colores hex. Por defecto `"verde"`.
     */
    paleta?: PaletaInput;
    /** Rango `[mínimo, máximo]` de dos colores; `paleta` tiene prioridad. */
    colorRange?: [string, string];
    emptyColor?: string;
    stroke?: string;
    formatValue?: (valor: number, municipio: Municipio) => string;
    /** Zoom con la rueda y pan arrastrando (doble clic reinicia). */
    zoom?: boolean | {
        min?: number;
        max?: number;
    };
    /** Etiqueta sobre cada municipio: `true`/`"nombre"` o una función. */
    etiquetas?: boolean | "nombre" | ((municipio: Municipio) => string);
    colorEtiqueta?: string;
    ariaLabel?: string;
    className?: string;
};
/**
 * Mapa choropleth de los municipios de un estado. Carga la geometría del estado
 * bajo demanda (un chunk por estado, alta resolución de INEGI). SVG puro, sin
 * librería de mapas ni API key.
 */
declare function MapaMunicipios({ estado, data, onSelect, paleta, colorRange, emptyColor, stroke, formatValue, zoom, etiquetas, colorEtiqueta, ariaLabel, className, }: Props): react.JSX.Element;

export { MapaMunicipios, type Municipio, type MunicipiosEstadoTopo, cargaMunicipios, municipio, municipioDeCoordenada, municipios };
